from taf.internal.cloud.lcmaas.client.lcmaas.v1 import VisApi, ViPatch, ViImageRegistry, ViIn


class VIsv1(object):
    def __init__(self, api_client):
        self.vi_api_v1 = VisApi(api_client=api_client)

    def get_vis(self, neat_name=None):
        return self.vi_api_v1.get_v_is(neat=neat_name)

    def update_vi(self, vi_name, image_registry_addr, image_registry_user=None, image_registry_pwd=None,
                  image_registry_ca_certs=None, kubeconfig=None):
        if image_registry_ca_certs is not None:
            image_registry_ca_certs = 'cert=\n' + image_registry_ca_certs
        vi_image_registry = ViImageRegistry(addr=image_registry_addr,
                                            user=image_registry_user,
                                            password=image_registry_pwd,
                                            ca_certs=image_registry_ca_certs)
        vi_patch_data = ViPatch(kube_config=kubeconfig, image_registry=vi_image_registry)
        return self.vi_api_v1.update_vi_by_name(vi_name=vi_name, vi_patch=vi_patch_data)

    def delete_vi(self, vi_name):
        return self.vi_api_v1.delete_vi_by_name(vi_name=vi_name)

    def create_vi(self, vi_name, kube_config, image_registry_addr, image_registry_user, image_registry_pwd,
                  image_registry_ca_certs=None):
        if image_registry_ca_certs is not None:
            image_registry_ca_certs = 'cert=\n' + image_registry_ca_certs
        vi_image_registry = ViImageRegistry(addr=image_registry_addr,
                                            user=image_registry_user,
                                            password=image_registry_pwd,
                                            ca_certs=image_registry_ca_certs)
        vi_in_data = ViIn(name=vi_name, kube_config=kube_config, image_registry=vi_image_registry)

        return self.vi_api_v1.create_vi(vi_in_data)
